import {useState} from 'react'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {Heading, Box, UnderlineNav} from '@primer/styled-react'
import {Flash} from '@primer/react'
import type {Image} from '@github-ui/github-hosted-runners-settings/types/image'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'

import CustomImagesList from '../views/components/shared/CustomImagesList'
import SearchInput from '../views/components/shared/SearchInput'

import {useLocation} from '@github-ui/react-router'

export interface CustomImagesManagementPayload {
  entityLogin: string
  images: Image[]
  isEnterprise: boolean
  canWriteCustomImages: boolean
  navigationPaths?: {
    policies: string
    runners: string
    runnerGroups: string
    customImages: string
    oidcConfiguration?: string
  }
}

export function CustomImagesManagement() {
  const {entityLogin, images, isEnterprise, canWriteCustomImages, navigationPaths} =
    useRoutePayload<CustomImagesManagementPayload>()
  const [searchQuery, setSearchQuery] = useState('')
  const location = useLocation()

  // Check if feature flag is enabled to determine the appropriate limit
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const isLimitIncreaseEnabled = useFeatureFlag('ims_customer_image_definitions_limit_increase')
  const imageLimit = isLimitIncreaseEnabled ? 250 : 50

  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showOIDCConfigurationNavItem = useFeatureFlag('actions_oidc_settings_ui')

  return (
    <>
      {isEnterprise ? (
        <>
          <Heading
            as="h1"
            className="business-content"
            data-testid="custom-images-title"
            sx={{fontSize: 'var(--text-title-size-medium)', paddingBottom: 2}}
          >
            Actions
          </Heading>
          <Box sx={{borderBottom: '1px solid', borderColor: '#3d444db3', mb: 3}} />
        </>
      ) : (
        <>
          <Heading as="h2" className="text-normal" data-testid="custom-images-title" sx={{fontSize: 'var(--h2-size)'}}>
            Custom images
          </Heading>
          <Box sx={{borderBottom: '1px solid', borderColor: 'border.default', paddingTop: 2, mb: 3}} />
        </>
      )}

      {isEnterprise && navigationPaths && (
        <UnderlineNav aria-label="Actions navigation" sx={{mb: 3, px: 0}} className="list-style-none">
          <UnderlineNav.Item href={navigationPaths.policies}>Policies</UnderlineNav.Item>
          <UnderlineNav.Item href={navigationPaths.runners}>Runners</UnderlineNav.Item>
          <UnderlineNav.Item href={navigationPaths.runnerGroups}>Runner groups</UnderlineNav.Item>
          <UnderlineNav.Item
            href={navigationPaths.customImages}
            aria-current={location.pathname === navigationPaths.customImages ? 'page' : undefined}
          >
            Custom images
          </UnderlineNav.Item>
          {showOIDCConfigurationNavItem && navigationPaths.oidcConfiguration && (
            <UnderlineNav.Item href={navigationPaths.oidcConfiguration}>OIDC Configuration</UnderlineNav.Item>
          )}
        </UnderlineNav>
      )}

      <Box sx={{mb: 3}} as="p">
        Manage your custom images and their versions.
      </Box>

      {images.length >= imageLimit && (
        <Box sx={{mb: 3}}>
          <Flash variant="warning">
            Custom Image definitions limit <code>({imageLimit})</code> reached. New image definitions will not be
            created.
            <br />
            To create new image definitions, you must delete existing definitions or contact support to discuss
            increasing the limit.
          </Flash>
        </Box>
      )}

      <SearchInput onSetSearchQuery={setSearchQuery} />
      <CustomImagesList
        entityLogin={entityLogin}
        images={images}
        isEnterprise={isEnterprise}
        searchQuery={searchQuery}
        canWriteCustomImages={canWriteCustomImages}
      />
    </>
  )
}
